'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let H,I,W,R,scopeConfig=null,localIncluded=null,rawWeekly=null,selectionDraft=null,lines=[],view='brief',bucket='done_last';
const titles={brief:['경영 브리핑','제품의 약속과 예외를 한눈에. 근거를 확인하고 다음 대화를 준비하세요.'],portfolio:['제품 포트폴리오','같은 기준으로 제품군을 비교하고, 개별 과제의 근거까지 확인하세요.'],roadmap:['통합 로드맵','최초 계획과 현재 날짜를 비교합니다. 일정 변경은 전망이나 승인으로 해석하지 않습니다.'],review:['주간 리뷰','지난주 결과에서 이번 주 약속까지. 회의 전 확인할 업무를 모았습니다.']};
const buckets={done_last:'지난주 완료',carry:'지난주에서 이어짐',new_week:'이번 주 신규',due_week:'이번 주 마감'};
const addDays=(s,n)=>{const d=new Date(s+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const empty=s=>`<div class="empty">${esc(s)}</div>`;
const link=x=>`<a href="https://plm.abyz-lab.work/work_packages/${Number(x.id)}" target="_blank" rel="noopener noreferrer">${esc(x.display_id||'#'+x.id)} ↗</a>`;
function model(){const selected=activeProjectIds();if(selected===null){lines=[];return;}const included=new Set(selected);lines=(I.product_lines||[]).map(l=>({...l,projects:l.regulatory?l.projects:(l.projects||[]).filter(id=>included.has(id))})).filter(l=>l.regulatory||l.projects.length).map(l=>{const names=new Set((I.project_status||[]).filter(p=>(l.projects||[]).includes(p.identifier)).map(p=>p.project));const projects=(H.project_health||[]).filter(p=>names.has(p.project));const ms=(I.milestones||[]).filter(m=>(l.projects||[]).includes(m.project_identifier));const sum=k=>projects.reduce((n,p)=>n+(Number(p[k])||0),0);return {...l,selectedProjectIds:l.projects,names,projects,ms,open:sum('open'),overdue:sum('overdue'),hold:sum('on_hold'),past:ms.filter(m=>m.date&&m.date<H.today),next:ms.filter(m=>m.date&&m.date>=H.today).sort((a,b)=>a.date.localeCompare(b.date))[0],slipped:ms.filter(m=>(m.slip_days||0)>30)};});}
function scoped(){const scope=$('#scope').value,q=$('#search').value.trim().toLowerCase();return lines.filter(l=>(scope==='all'||l.name===scope)&&(!q||l.name.toLowerCase().includes(q)||[...l.names].some(n=>n.toLowerCase().includes(q))));}
function badge(l){return l.past.length?'<span class="badge red">기한 지난 마일스톤</span>':l.overdue?'<span class="badge warn">마감 초과 업무</span>':!l.ms.some(m=>m.date)?'<span class="badge grey">일정 근거 부족</span>':'<span class="badge">기한 초과 신호 없음</span>';}
const total=(ls,k)=>ls.reduce((n,l)=>n+l[k],0);
function kpis(ls){return `<div class="kpis"><div class="kpi accent"><span>조회 중인 제품군</span><b>${ls.length}<small> 개</small></b><small>공통 조회 범위 적용</small></div><div class="kpi"><span>열린 업무</span><b>${total(ls,'open')}<small> 건</small></b><small>보류 ${total(ls,'hold')}건 별도</small></div><div class="kpi"><span>마감 초과 업무</span><b>${total(ls,'overdue')}<small> 건</small></b><small>사업 영향 판단과 구분</small></div><div class="kpi"><span>기한 지난 마일스톤</span><b>${ls.reduce((n,l)=>n+l.past.length,0)}<small> 건</small></b><small>원본 스냅숏의 날짜 기준</small></div></div>`;}
function brief(ls){const priority=ls.filter(l=>l.past.length||l.overdue||l.slipped.length).sort((a,b)=>b.past.length-a.past.length||b.overdue-a.overdue);const soon=ls.flatMap(l=>l.ms.filter(m=>m.date&&m.date>=H.today).map(m=>({...m,line:l.name}))).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5);return kpis(ls)+`<div class="sectionhead"><div><h2>지금 확인할 예외</h2><p>규칙으로 선별한 검토 대상입니다. 실제 결정 요청·위험 예측은 아닙니다.</p></div><span>EXCEPTIONS FIRST</span></div><div class="grid"><section class="panel"><div class="paneltitle"><h3>일정과 업무의 신호</h3><small>${priority.length}개 제품군</small></div>${priority.slice(0,5).map((l,i)=>`<div class="issue"><span class="index">0${i+1}</span><div><h3>${esc(l.name)}</h3><p>${l.past.length?'마일스톤 기한 경과 '+l.past.length+'건 · ':''}마감 초과 업무 ${l.overdue}건${l.slipped.length?' · 최초 계획 대비 30일 초과 변경 '+l.slipped.length+'건':''}</p><button class="textbtn" data-line="${esc(l.name)}">근거 확인 →</button></div></div>`).join('')||empty('현재 범위에 기한 초과 신호가 없습니다.')}<div class="note">확인할 대화: 변경 원인은 무엇이며, 다음 관문에 어떤 영향이 있나요? 날짜를 바꾼 사실만으로 문제가 해결되었다고 보지 않습니다.</div></section><section class="panel"><div class="paneltitle"><h3>다가오는 마일스톤</h3><small>현재 등록 날짜순</small></div>${soon.map(m=>`<div class="row"><div><span class="eyebrow">${esc(m.date)}</span><p>${esc(m.line)}</p><strong>${esc(m.subject)}</strong></div><button class="textbtn" data-ms="${m.id}">상세 ↗</button></div>`).join('')||empty('다가오는 날짜가 등록되어 있지 않습니다.')}</section></div><div class="sectionhead"><div><h2>데이터와 인허가</h2><p>제품군 조회 범위와 회사 전체 집계를 명확히 구분합니다.</p></div></div><div class="grid"><section class="panel"><h3>판단 가능한 범위</h3><p>기한 초과는 등록된 날짜 기준입니다. 완료 여부와 최신 상태는 원본에서 확인하세요.</p><div class="note">실제 승인·결정 기록 및 출시 영향 분석은 미연결입니다. 직원 갱신 빈도를 성과 지표로 사용하지 않습니다.</div></section><section class="panel"><div class="paneltitle"><h3>인허가 요청</h3><small>회사 전체 · 필터 외 별도 참고</small></div>${R?`<div class="row"><span>열린 요청</span><strong>${Number(R.open)||0}건</strong></div><div class="row"><span>원본 규칙상 검토 지연</span><strong>${Number(R.review_delay)||0}건</strong></div><p>등록부 ${R.registry_connected?'연결됨':'미연결'} · 제품별 출시 준비도는 산정하지 않습니다.</p>`:empty('인허가 스냅숏을 불러오지 못했습니다.')}</section></div>`;}
function portfolio(ls){return kpis(ls)+`<div class="sectionhead"><div><h2>제품군별 현황</h2><p>예외 신호와 일정 근거를 함께 확인하세요.</p></div><span>PORTFOLIO OVERVIEW</span></div><div class="cards">${ls.map(l=>`<article class="product">${badge(l)}<h3>${esc(l.name)}</h3><p>${l.projects.length}개 과제 · 날짜 있는 마일스톤 ${l.ms.filter(m=>m.date).length}개</p><div class="metrics"><div><b>${l.open}</b><span>열린 업무</span></div><div><b>${l.overdue}</b><span>마감 초과</span></div><div><b>${l.hold}</b><span>보류</span></div></div><p>${l.next?'다음 관문 · '+esc(l.next.date)+'<br>'+esc(l.next.subject):'다가오는 관문 날짜가 없습니다.'}</p><button class="textbtn" data-line="${esc(l.name)}">과제와 일정 근거 보기 →</button></article>`).join('')}</div>`;}
function roadmap(ls){const months=Number($('#range')?.value||viewPreferences.dev.range||9),begin=new Date(H.today+'T00:00:00Z');begin.setUTCDate(1);begin.setUTCMonth(begin.getUTCMonth()-3);const start=begin.toISOString().slice(0,10),finish=new Date(begin);finish.setUTCMonth(finish.getUTCMonth()+months);const end=finish.toISOString().slice(0,10),span=Date.parse(end)-Date.parse(start),pos=d=>Math.max(1,Math.min(99,(Date.parse(d)-Date.parse(start))/span*100));const all=ls.flatMap(l=>l.ms.map(m=>({...m,line:l.name})));return '<div class="timelinehead"><label>표시 기간 <select id="range"><option value="9" '+(months===9?'selected':'')+'>과거 3개월 + 이후 6개월</option><option value="15" '+(months===15?'selected':'')+'>과거 3개월 + 이후 12개월</option></select></label><span>◇ 최초 계획 · ◆ 현재 등록일 · 세로선: 스냅숏 기준일</span></div><div class="tablewrap"><div class="schedule"><div class="scheduleaxis"><span>과제 / 마일스톤</span><div>'+Array.from({length:months},(_,i)=>{const d=new Date(begin);d.setUTCMonth(d.getUTCMonth()+i);return '<span>'+d.getUTCFullYear()+'.'+String(d.getUTCMonth()+1).padStart(2,'0')+'</span>';}).join('')+'</div></div>'+ls.map(l=>'<h3 class="schedule-family">'+esc(l.name)+'</h3>'+l.projects.map(p=>{const ms=l.ms.filter(m=>m.project===p.project);return '<div class="schedule-project">'+esc(p.project)+'</div>'+ (ms.length?ms.map(m=>{const inside=d=>d&&d>=start&&d<end,first=inside(m.first_planned),cur=inside(m.date);return '<div class="schedule-row"><div class="schedule-label"><button class="textbtn" data-ms="'+m.id+'">'+esc(m.subject)+'</button><small>최초 '+esc(m.first_planned||'미등록')+' → 현재 '+esc(m.date||'미등록')+'</small><small>차이 '+(m.slip_days==null?'산정 불가':m.slip_days+'일')+' · 변경 사유: 원본 미제공</small></div><div class="schedule-track"><span class="today-line" style="left:'+pos(H.today)+'%"></span>'+(first&&cur?'<span class="slip-line" style="left:'+Math.min(pos(m.first_planned),pos(m.date))+'%;width:'+Math.abs(pos(m.date)-pos(m.first_planned))+'%"></span>':'')+(first?'<button class="date-mark first" data-ms="'+m.id+'" style="left:'+pos(m.first_planned)+'%" aria-label="'+esc(m.subject+' 최초 계획 '+m.first_planned)+'">◇</button>':'')+(cur?'<button class="date-mark current '+(m.date<H.today?'late':'')+'" data-ms="'+m.id+'" style="left:'+pos(m.date)+'%" aria-label="'+esc(m.subject+' 현재 등록일 '+m.date)+'">◆</button>':'<span class="outside">'+(m.date?'현재 일정: 표시 기간 밖':'현재 날짜 미등록')+'</span>')+'</div></div>';}).join(''):'<p class="no-schedule">등록된 마일스톤 없음 · 일정 약속 여부 원본 확인</p>');}).join('')).join('')+'</div></div><p class="comparison-note">기준일 '+esc(H.today)+' · 현재 날짜 경과는 완료 지연 확정이 아닙니다. 변경 횟수·날짜 차이는 사실 기록이며 변경 이유는 제공되지 않았습니다.</p>';}
function weeklyMatrix(ls){if(!W)return empty('주간 스냅숏이 없습니다.');const wl=(W.lines||[]).filter(l=>ls.some(x=>x.name===l.name));return '<div class="sectionhead"><div><h2>주간 업무 비교</h2><p>이전 주 완료와 이월, 이번 주 신규·마감을 동시에 비교합니다. 범주 간 중복 가능 · '+esc(W.week?.anchor||'')+' ~ '+esc(W.week?.next_anchor||'')+'</p></div></div><section class="panel tablewrap compact"><table class="weekly-matrix"><thead><tr><th>제품군</th>'+Object.values(buckets).map(v=>'<th>'+v+'</th>').join('')+'</tr></thead><tbody>'+wl.map(l=>'<tr><td><strong>'+esc(l.name)+'</strong></td>'+Object.entries(buckets).map(([k,label])=>'<td>'+(l[k]?.length?'<button class="count-button" data-week-line="'+esc(l.name)+'" data-week-bucket="'+k+'" aria-label="'+esc(l.name+' '+label+' '+l[k].length+'건 상세')+'">'+l[k].length+'</button>':'<span class="muted">0</span>')+'</td>').join('')+'</tr>').join('')+'<tr class="total-row"><td>합계</td>'+Object.keys(buckets).map(k=>'<td>'+wl.reduce((n,l)=>n+(l[k]||[]).length,0)+'</td>').join('')+'</tr></tbody></table></section>';}
function render(){if(!H||!I)return;view=location.hash.slice(1);if(!titles[view])view='brief';const ls=scoped();$('#page-title').textContent=titles[view][0];$('#page-desc').textContent=titles[view][1];document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#scope-note').textContent=ls.length+'개 제품군 · 모든 화면 동일 범위';$('#content').innerHTML=!ls.length?empty('검색 조건에 맞는 제품군이 없습니다. 필터를 초기화해 주세요.'):({brief,portfolio,roadmap,review}[view])(ls);}
function show(html){$('#detail-body').innerHTML=html;$('#detail').showModal();}
function lineDetail(name){const l=lines.find(x=>x.name===name);if(!l)return;const items=(H.items||[]).filter(x=>l.names.has(x.project));show(`${badge(l)}<h2>${esc(l.name)}</h2><p>소속 ${l.projects.length}개 과제 · ${H.today} 기준</p><h3>과제별 업무 현황</h3><table><thead><tr><th>과제</th><th>열린 업무</th><th>마감 초과</th><th>보류</th></tr></thead><tbody>${l.projects.map(p=>`<tr><td>${esc(p.project)}</td><td>${Number(p.open)||0}</td><td>${Number(p.overdue)||0}</td><td>${Number(p.on_hold)||0}</td></tr>`).join('')||'<tr><td colspan="4">집계 과제 없음</td></tr>'}</tbody></table><h3>스냅숏에 포함된 예외 업무</h3><p>전체 업무 목록이 아닌 원본의 예외 추출 목록입니다.</p>${items.map(x=>`<div class="row"><div><strong>${esc(x.subject)}</strong><p>${esc(x.status)} · 마감 ${esc(x.due||'미등록')}</p></div>${link(x)}</div>`).join('')||empty('추출된 예외 업무 없음')}<div class="note">일정 근거 부족과 사업 위험을 구분하세요. 예외가 없다는 사실만으로 정상 진행이나 출시 가능을 보장하지 않습니다.</div>`);}
function milestoneDetail(id){const m=(I.milestones||[]).find(x=>x.id===Number(id));if(!m)return;show(`<div class="eyebrow">MILESTONE EVIDENCE</div><h2>${esc(m.subject)}</h2><p>${esc(m.project)}</p><div class="row"><span>최초 계획</span><strong>${esc(m.first_planned||'미등록')}</strong></div><div class="row"><span>현재 등록 날짜</span><strong>${esc(m.date||'미등록')}</strong></div><div class="row"><span>변경 횟수</span><strong>${Number(m.changes)||0}회</strong></div><div class="row"><span>최초 계획 대비</span><strong>${m.slip_days==null?'산정 불가':m.slip_days+'일'}</strong></div><div class="row"><span>변경 사유</span><strong>원본에 제공되지 않음</strong></div><p>날짜 변경 이력은 승인·결정 완료를 의미하지 않습니다.</p><div class="note">날짜의 차이를 보여주는 사실 기록입니다. 실제 완료·승인 여부나 최신 전망은 원본 확인이 필요합니다.</div><p style="margin-top:20px">${link(m)}</p>`);}
$('#scope').addEventListener('change',render);$('#search').addEventListener('input',render);$('#reset').addEventListener('click',()=>{$('#scope').value='all';$('#search').value='';render();});$('#close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close();});$('#method').onclick=()=>show('<h2>지표와 데이터 기준</h2><h3>데이터 원천</h3><p>plm-dash.work의 health / insights / weekly / ra JSON을 읽은 스냅숏입니다. 자동 갱신은 연결하지 않았습니다.</p><h3>조회 범위</h3><p>선택한 제품군과 검색 조건은 네 화면에 동일하게 적용됩니다. 인허가 회사 전체 참고 집계는 별도로 표시합니다.</p><h3>해석 원칙</h3><p>열린 업무·기한 초과·보류는 원본 과제 집계를 합산합니다. 보류는 별도 표시합니다. 마일스톤 기한 경과는 현재 등록 날짜와 스냅숏 기준일을 비교합니다. 실제 완료 여부는 원본 확인이 필요합니다.</p><h3>제공하지 않는 판단</h3><p>실제 결정·승인, 미래 일정 예측, 인력 성과, 출시 준비도는 계산하지 않습니다. 개인정보 최소화를 위해 직원별 이름과 지표는 포함하지 않습니다.</p>');
document.addEventListener('click',e=>{const l=e.target.closest('[data-line]'),m=e.target.closest('[data-ms]'),b=e.target.closest('[data-bucket]');if(l)lineDetail(l.dataset.line);if(m)milestoneDetail(m.dataset.ms);if(b){bucket=b.dataset.bucket;render();}});document.addEventListener('change',e=>{if(e.target.id==='range')render();});window.addEventListener('hashchange',render);
async function init(){const res=await Promise.allSettled(['health','insights','weekly','ra','config/tracked-projects'].map(async n=>{const r=await fetch('data/'+n+'.json',{cache:'no-store'});if(!r.ok)throw Error(n);return r.json();}));H=res[0].status==='fulfilled'?res[0].value:null;I=res[1].status==='fulfilled'?res[1].value:null;W=res[2].status==='fulfilled'?res[2].value:null;R=res[3].status==='fulfilled'?res[3].value:null;if(!H||!I){$('#snapshot').textContent='필수 스냅숏을 읽지 못했습니다.';$('#content').innerHTML=empty('데이터를 불러오지 못했습니다. 잠시 후 페이지를 새로고침해 주세요.');return;}const configResult=res[4];const configCandidate=configResult?.status==='fulfilled'?configResult.value:null;scopeConfig=configCandidate&&configCandidate.version===1&&Array.isArray(configCandidate.excluded)&&configCandidate.excluded.every(x=>typeof x==='string')&&typeof configCandidate.updated_at==='string'&&!Number.isNaN(Date.parse(configCandidate.updated_at))?configCandidate:null;historicalSnapshots={health:H,insights:I,weekly:W,ra:R};rawWeekly=W;loadLocalSelection();applySelectionScope();for(const l of lines){const o=document.createElement('option');o.value=l.name;o.textContent=l.name;$('#scope').append(o);}const date=new Date(H.generated_at);$('#basis').textContent=Number.isNaN(date.getTime())?H.today:new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(date)+' KST';$('#snapshot').textContent='스냅숏 기준 '+H.today+' · 자동 갱신 미연결 · 현재 OpenProject 상태와 다를 수 있습니다.';render();}init().catch(()=>{$('#content').innerHTML=empty('화면 초기화에 실패했습니다. 페이지를 새로고침해 주세요.');});

