function devContent(ls){const maxOpen=Math.max(1,...ls.map(l=>Math.max(l.open,l.hold,l.overdue))),allDates=ls.flatMap(l=>l.ms.flatMap(m=>[m.first_planned,m.date]).filter(Boolean)),minDate=allDates.slice().sort()[0]||H.today,maxDate=allDates.slice().sort().at(-1)||addDays(H.today,1),span=Math.max(86400000,Date.parse(maxDate)-Date.parse(minDate)),px=d=>8+(Date.parse(d)-Date.parse(minDate))/span*184,bar=(n,kind)=>'<span class="work-track"><i class="'+kind+'" style="width:'+(n?Math.max(2,n/maxOpen*100):0)+'%"></i></span><b>'+n+'</b>',short=d=>d?d.slice(2).replaceAll('-','.'):'미등록';return executiveExceptions(ls)+'<details class="fold-section" id="product-comparison-details"><summary><strong>제품군별 업무량·일정 비교</strong><small>'+ls.length+'개 제품군 · 펼쳐서 공통 척도 비교</small></summary><div class="visual-key"><span><i class="key-open"></i>열린 업무</span><span><i class="key-overdue"></i>마감 초과 <small>열린 업무의 부분집합</small></span><span><i class="key-hold"></i>보류 <small>별도 집계</small></span><strong>막대 공통 척도 0–'+maxOpen+'건</strong></div><div class="visual-heading"><h2>제품군별 개발 현황</h2><span>원본 제품군 순</span></div><p class="mobile-scroll-hint">표를 좌우로 이동해 업무·일정을 비교하세요. 제품군은 왼쪽에 고정됩니다.</p><section class="panel tablewrap compact" tabindex="0" aria-label="제품군 시각 비교표"><table class="development-table visual-development"><thead><tr><th>제품군 / 상태</th><th>업무량 <small>건수 · 공통 척도</small></th><th>일정 변경 <small>◇ 최초 → ● 현재 / 공통 날짜축</small></th><th>다음 마일스톤 / 원본 업무</th></tr></thead><tbody>'+ls.map(l=>{const changed=l.ms.filter(m=>m.first_planned&&m.date&&m.first_planned!==m.date).sort((a,b)=>Math.abs(b.slip_days||0)-Math.abs(a.slip_days||0))[0],issue=(H.items||[]).filter(x=>l.names.has(x.project)&&x.status!=='On Hold')[0],status=l.past.length?'◆ 날짜 경과 '+l.past.length:l.overdue?'▲ 마감 초과 '+l.overdue:!l.ms.some(m=>m.date)?'○ 일정 미등록':'● 초과 신호 없음';return '<tr><td><button class="visual-product textbtn" data-line="'+esc(l.name)+'">'+esc(l.name)+' →</button><span class="visual-status '+(l.past.length?'late':l.overdue?'warn':'')+'">'+status+'</span><details class="project-details"><summary>'+l.projects.length+'개 과제</summary>'+l.projects.map(p=>'<div class="project-evidence">'+esc(p.project)+'<small>열린 '+p.open+' · 마감 초과 '+p.overdue+'</small></div>').join('')+(l.selectedProjectIds||[]).filter(id=>!l.projects.some(p=>p.project===(I.project_status||[]).find(x=>x.identifier===id)?.project)).map(id=>'<div class="project-evidence">'+esc(id)+'<small>집계자료 미제공 · 0건 또는 정상으로 판정하지 않음</small></div>').join('')+'</details></td><td><div class="work-bars"><span>열린</span>'+bar(l.open,'key-open')+'<span>초과</span>'+bar(l.overdue,'key-overdue')+'<span>보류</span>'+bar(l.hold,'key-hold')+'</div></td><td>'+(changed?'<button class="schedule-mini" data-ms="'+changed.id+'" aria-label="'+esc(changed.project+' '+changed.subject+' 최초 '+changed.first_planned+' 현재 '+changed.date+' '+changed.slip_days+'일 변경, 사유 미제공')+'"><svg viewBox="0 0 200 24" role="img" aria-label="최초 계획과 현재 날짜 비교"><line x1="8" y1="12" x2="192" y2="12" stroke="#e0e6e0"/><line x1="'+px(changed.first_planned)+'" y1="12" x2="'+px(changed.date)+'" y2="12" stroke="'+(changed.slip_days>0?'#b36d3e':'#29756c')+'" stroke-width="3"/><polygon points="'+px(changed.first_planned)+',6 '+(px(changed.first_planned)+5)+',12 '+px(changed.first_planned)+',18 '+(px(changed.first_planned)-5)+',12" fill="#fff" stroke="#786e56"/><circle cx="'+px(changed.date)+'" cy="12" r="5" fill="'+(changed.slip_days>0?'#b36d3e':'#29756c')+'"/></svg><span>'+short(changed.first_planned)+' → '+short(changed.date)+' <b>'+(changed.slip_days>0?'+':'')+changed.slip_days+'일</b></span><small class="visual-ellipsis" title="'+esc(changed.project+' · '+changed.subject)+'">'+esc(changed.project+' · '+changed.subject)+'</small></button>':'<span class="no-data">비교할 변경 날짜 없음</span>')+'</td><td>'+(l.next?'<button class="textbtn visual-next" data-ms="'+l.next.id+'"><b>'+short(l.next.date)+'</b> '+esc(l.next.subject)+'</button>':'<span class="no-data">다음 날짜 미등록</span>')+(issue?'<div class="evidence-item visual-ellipsis" title="'+esc(issue.project+' · '+issue.subject)+'">'+link(issue)+' · '+esc(issue.project+' · '+issue.subject)+'</div><small class="cause-unknown">원인 미확인</small>':'')+'</td></tr>';}).join('')+'</tbody></table><p class="comparison-note">일정축 '+esc(minDate)+'–'+esc(maxDate)+' · 원인·변경 사유는 원본 미제공.</p></section></details>'+review(ls)+'<details class="timeline-disclosure"><summary>전체 마일스톤 <small>과제별 최초 계획 ↔ 현재 일정</small></summary><section class="panel compact">'+roadmap(ls)+'</section></details>';}
function raExpandedContent(){if(!R)return empty('전사 인허가 스냅숏을 읽지 못했습니다.');const reg=R.registry||{},market=$('#market').value,family=$('#family').value,q=$('#ra-search').value.trim().toLowerCase();const match=v=>!q||String(v||'').toLowerCase().includes(q);const entries=[];for(const [fam,models] of Object.entries(reg.family_models||{})){if(family!=='all'&&family!==fam)continue;for(const m of models||[])for(const [country,c] of Object.entries(m.cells||{})){if(market!=='all'&&country!==market)continue;if(!match([fam,m.model,m.series,country,...(c.types||[])].join(' ')))continue;entries.push({family:fam,model:m.model,series:m.series,country,...c});}}
const obs=(reg.obligations||[]).filter(o=>(market==='all'||o.country===market)&&(o.scope==='company'||family==='all'||o.family===family)&&(match([o.kind,o.type,o.family,o.country,...(o.models||[])].join(' ')))).sort((a,b)=>(a.date||'').localeCompare(b.date||''));const company=(reg.company||[]).filter(c=>(market==='all'||c.country===market)&&match([c.country,c.type,c.state].join(' ')));const requests=(R.open_requests||[]).filter(x=>match(x.subject));const expired=entries.filter(x=>x.state==='만료').length;const pending=entries.filter(x=>/진행|갱신|신청|심사/.test(x.state||'')).length;return `<div class="sectionhead"><div><h2>의무 일정</h2><p>전사 의무 중 기한 경과·90일 이내 일정 · 시장·검색 적용, 회사 공통은 제품군 필터 제외 · 기준 ${esc(R.today)}</p></div></div><section class="panel compact">${obs.filter(o=>o.overdue||(o.date&&o.date<=addDays(R.today,90))).map(o=>`<div class="urgent-obligation"><span class="badge ${o.overdue?'red':'warn'}">${o.overdue?'기한 경과':'90일 이내'}</span><strong>${esc(o.date||'미제공')}</strong><div>${esc(o.country)} · ${esc(o.type)} · ${esc(o.kind)}<small>${esc(o.scope==='company'?'회사 공통 · 제품군 필터 제외':o.family||'제품')} ${esc((o.models||[]).join(', '))} · 등록 상태 ${esc(o.state||'미제공')}</small></div></div>`).join('')||empty('조회 범위에 기한 경과·90일 이내 의무가 없습니다.')}<p class="comparison-note">회사 공통 의무 ${obs.filter(o=>o.scope==='company').length}건 · 제품 범위 의무 ${obs.filter(o=>o.scope!=='company').length}건. 날짜가 가까운 의무를 우선 표시합니다. 회사 허가·요청은 제품군 필터와 별도 범위를 아래에 표시합니다.</p></section><div class="summary-strip"><span>필터 내 모델·시장 등록 ${entries.length}건</span><span>등록 상태 만료 ${expired}건</span><span>전체 원천 등록부 제품 ${reg.counts?.rows||0}행 / 회사 ${reg.counts?.company_rows||0}행</span></div><div class="sectionhead"><div><h2>제품 등록부</h2><p>등록부 동기화 ${esc(reg.synced_at||'시각 미제공')} · 미표시 시장은 미취득으로 단정하지 않습니다.</p></div><span>PRODUCT REGISTRY</span></div><section class="panel tablewrap"><table><thead><tr><th>제품군 / 시리즈</th><th>모델</th><th>시장</th><th>등록 종류</th><th>상태</th><th>만료일</th></tr></thead><tbody>${entries.map(c=>`<tr><td>${esc(c.family)}<small>${esc(c.series)}</small></td><td><strong>${esc(c.model)}</strong></td><td>${esc(c.country)}</td><td>${esc((c.types||[]).join(' · '))}</td><td><span class="badge ${c.state==='만료'?'red':/진행|갱신/.test(c.state)?'warn':''}">${esc(c.state||'미제공')}</span></td><td>${esc(c.expiry||'미제공')}</td></tr>`).join('')||'<tr><td colspan="6">조회 조건에 해당하는 등록 정보가 없습니다.</td></tr>'}</tbody></table></section><div class="sectionhead"><div><h2>갱신·만료 및 후속 의무</h2><p>날짜·범위·종류를 기준으로 확인합니다. 공란은 ‘의무 없음’을 뜻하지 않습니다.</p></div><span>OBLIGATIONS</span></div><section class="panel tablewrap"><table><thead><tr><th>의무일</th><th>범위 / 제품</th><th>시장</th><th>등록 종류</th><th>의무</th><th>상태</th></tr></thead><tbody>${obs.map(o=>`<tr><td>${esc(o.date||'미제공')}</td><td>${esc(o.scope==='company'?'회사':o.family||'제품')}<small>${esc((o.models||[]).join(', '))}</small></td><td>${esc(o.country)}</td><td>${esc(o.type)}</td><td>${esc(o.kind)}</td><td><span class="badge ${o.overdue?'red':'grey'}">${o.overdue?'기한 경과':esc(o.state||'예정')}</span></td></tr>`).join('')||'<tr><td colspan="6">조회 조건에 해당하는 의무 일정이 없습니다.</td></tr>'}</tbody></table></section><div class="sectionhead"><div><h2>회사 허가·인증</h2><p>시장·검색 필터 적용 · 제품군에 종속되지 않는 회사 자격입니다.</p></div></div><section class="panel tablewrap"><table><thead><tr><th>시장</th><th>허가·인증</th><th>상태</th><th>만료일</th><th>다음 의무</th></tr></thead><tbody>${company.map(c=>`<tr><td>${esc(c.country)}</td><td>${esc(c.type)}</td><td>${esc(c.state)}</td><td>${esc(c.expiry||'미제공')}</td><td>${esc(c.next_duty||'미제공')}<small>${esc(c.next_date||'')}</small></td></tr>`).join('')||'<tr><td colspan="5">조회 조건에 해당하는 회사 허가가 없습니다.</td></tr>'}</tbody></table></section><div class="sectionhead"><div><h2>요청 처리 현황</h2><p>전사 전체 · 검색만 적용. 요청에 시장·제품군 식별자가 없어 위 필터로 분류하지 않습니다.</p></div><span>REQUEST PIPELINE</span></div><section class="panel"><div class="request-summary">${[...new Set(requests.map(x=>x.status))].map(s=>`<span class="badge grey">${esc(s)} ${requests.filter(x=>x.status===s).length}</span>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>요청</th><th>실제 상태</th><th>희망일 / 마감</th><th>검토 신호</th><th>원본</th></tr></thead><tbody>${requests.map(x=>`<tr><td>${esc(x.subject)}<small>접수 ${esc(x.created)}</small></td><td>${esc(x.status)}</td><td>${esc(x.desired||'미등록')}<small>마감 ${esc(x.due||'미등록')}</small></td><td>${x.review_delay?'원본 규칙상 검토 지연':'검토 지연 신호 없음'}</td><td>${link(x)}</td></tr>`).join('')||'<tr><td colspan="5">검색에 맞는 열린 요청이 없습니다.</td></tr>'}</tbody></table></div><div class="note">원본 전체 집계 · 최근 ${Number(R.window_days)||180}일 완료 ${Number(R.done_180)||0}건 · 신규 취득 ${Number(R.new_acquisitions)||0}건 · 갱신 누락 ${Number(R.missed_renewals)||0}건. 신규 취득·갱신 누락의 개별 내역은 제공되지 않아 목록을 만들지 않았습니다.</div></section><div class="note">개발 연계 미확정 · 등록부의 제품 모델과 DR 개발 과제 간 검증된 연결 정보가 없습니다. 개발 단계와 인허가 상태를 자동 결합하지 않습니다.</div>`;}
function render(){if(!H||!I)return;const previousView=view==='ra'?'ra':'dev';captureViewDetails(previousView);const requestedView=consumeDashboardView();if(viewPreferencesReady&&previousView!==requestedView&&typeof window.scrollY==='number')viewPreferences[previousView].scrollY=window.scrollY;view=requestedView;const isRa=view==='ra';$('#dev-filters').hidden=isRa;$('#ra-filters').hidden=!isRa;$('#page-title').textContent=isRa?'전사 인허가':'DR 개발현황';$('#page-desc').textContent=isRa?'회사 전체의 제품 등록과 회사 허가, 갱신 의무, 요청 처리 현황입니다.':'제품군·과제의 예외와 일정, 주간 업무를 같은 기준으로 비교합니다.';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const sourceTime=isRa?(R?.generated||R?.registry?.synced_at):H.generated_at;const d=new Date(sourceTime);$('#basis').textContent=Number.isNaN(d.getTime())?'시각 미제공':new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(d)+' KST';const calendarParts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const cp=Object.fromEntries(calendarParts.map(p=>[p.type,p.value]));const kstToday=cp.year+'-'+cp.month+'-'+cp.day;const sourceParts=Number.isNaN(d.getTime())?null:Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d).map(p=>[p.type,p.value]));const sourceDay=sourceParts?sourceParts.year+'-'+sourceParts.month+'-'+sourceParts.day:null;const age=sourceDay?Math.max(0,Math.floor((Date.parse(kstToday)-Date.parse(sourceDay))/86400000)):null;$('#snapshot').classList.toggle('stale-snapshot',age!==null&&age>=1);$('#snapshot').textContent=(isRa?'범위: 회사 전체':'범위: DR 사업본부')+' · '+(age===null?'수집일 미확인':age>=1?age+'일 전 스냅숏 · 최신 상태 확인 필요':'오늘 수집된 스냅숏')+' · 오늘 '+kstToday+' (KST) · 자동 갱신 미연결';const ls=scoped().filter(l=>!l.regulatory);const configuredCount=activeProjectIds()?.length||0;const representedCount=lines.filter(l=>!l.regulatory).reduce((n,l)=>n+l.projects.length,0);$('#scope-note').textContent=activeProjectIds()!==null?'관심 과제 '+configuredCount+'개 · 집계 자료 '+representedCount+'개 · 집계자료 미제공 '+(configuredCount-representedCount)+'개 · 표시 '+ls.length+'개 제품군':'관심 과제 설정 확인 필요';const provenance=document.querySelector('#scope-provenance');if(provenance){provenance.hidden=isRa;provenance.textContent=activeProjectIds()!==null?'선택 기준: '+(localIncluded!==null?'이 기기에 저장한 관심 과제':'원본 선택의 로컬 복사')+' · 원본 설정 '+(scopeConfig?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(scopeConfig.updated_at))+' KST':'미연결')+' · 서버 전송 없음 · 집계자료 미제공: '+lines.filter(l=>!l.regulatory).flatMap(l=>(l.selectedProjectIds||[]).filter(id=>!l.projects.some(p=>p.project===(I.project_status||[]).find(x=>x.identifier===id)?.project))).join(', '):'선택 설정을 읽지 못해 개발 자료를 표시하지 않습니다. 전사 인허가는 별도 조회할 수 있습니다.';}$('#content').innerHTML=isRa?raContent():activeProjectIds()===null?empty('관심 과제 설정을 읽지 못했습니다. 개발 조회를 중단했습니다. 전사 인허가는 별도 메뉴에서 확인하세요.'):!ls.length?empty('조회 조건에 맞는 제품군이 없습니다.'):devContent(ls);setupSectionLayout(view);restoreViewDetails(view);restoreViewScroll(previousView!==view);if(viewPreferencesReady){viewPreferences.lastView=view;queueViewPreferenceSave();}updateLiveStatus();}
for(const id of ['market','family','ra-search'])$('#'+id).addEventListener(id==='ra-search'?'input':'change',render);$('#ra-reset').onclick=()=>{$('#market').value='all';$('#family').value='all';$('#ra-search').value='';render();};document.addEventListener('click',e=>{const b=e.target.closest('[data-devtab]');if(b){devTab=b.dataset.devtab;render();}});$('#method').onclick=()=>show('<h2>범위와 해석 기준</h2><h3>DR 개발현황</h3><p>제품군·과제·등록된 마일스톤·예외 업무·주간 집계를 조회합니다. RA 파트는 개발 제품군에서 제외합니다. 목표·개발 단계는 명시적 매핑이 없어 추정하지 않습니다.</p><h3>전사 인허가</h3><p>회사 전체의 제품 등록부·회사 허가·의무 일정·열린 요청을 표시합니다. 제품 등록의 단위는 모델×시장입니다. 회사 허가는 시장·검색, 요청은 검색만 적용하며 제품군 필터와 구분합니다.</p><h3>연결과 최신성</h3><p>두 영역 간 검증된 공통 식별자가 없어 제품 이름으로 추정 연결하지 않습니다. 원본 집계 생성시각과 읽기 확인시각을 구분합니다. 로컬 읽기 서버에 연결되면 열기·새로고침·자료 새로 확인 시 조회하며, 원본 집계가 생성된 시각의 자료이므로 실시간 작업 상태와 다를 수 있습니다. 실제 사업 기록을 수정하지 않습니다.</p>'+liveReadDetails());
const domainPopulate=setInterval(()=>{if(!H||!I)return;clearInterval(domainPopulate);document.querySelectorAll('#scope option').forEach(o=>{if(lines.find(l=>l.name===o.value)?.regulatory)o.remove();});for(const c of R?.registry?.columns||[]){const o=document.createElement('option');o.value=c;o.textContent=c;$('#market').append(o);}for(const f of R?.registry?.families||[]){const o=document.createElement('option');o.value=f;o.textContent=f;$('#family').append(o);}restoreInitialViewPreferences();render();startLiveUpdates();},50);

document.addEventListener('click',e=>{const b=e.target.closest('[data-week-line]');if(!b)return;const l=(W?.lines||[]).find(x=>x.name===b.dataset.weekLine),k=b.dataset.weekBucket;if(!l||!buckets[k])return;show('<h2>'+esc(l.name)+' · '+buckets[k]+'</h2><p>주간 원본 스냅숏의 실제 업무 목록입니다.</p><div class="tablewrap"><table><thead><tr><th>과제 / 업무</th><th>상태·날짜</th><th>원본</th></tr></thead><tbody>'+(l[k]||[]).map(x=>'<tr><td>'+esc(x.subject)+'<small>'+esc(x.project)+'</small></td><td>'+esc(x.status||'미제공')+'<small>마감 '+esc(x.due||'미등록')+'</small></td><td>'+link(x)+'</td></tr>').join('')+'</tbody></table></div>');});
