/* Default view keeps working exceptions visible; complete registers are opt-in. */
function review(ls){if(!W)return empty('주간 스냅숏이 없습니다.');const wl=(W.lines||[]).filter(l=>ls.some(x=>x.name===l.name)),totals=Object.fromEntries(Object.keys(buckets).map(k=>[k,wl.reduce((n,l)=>n+(l[k]||[]).length,0)])),totalMax=Math.max(1,...Object.values(totals)),max=Math.max(1,...wl.flatMap(l=>Object.keys(buckets).map(k=>(l[k]||[]).length)));return '<div class="visual-heading"><h2>주간 업무 흐름</h2><span>'+esc(W.week?.anchor||'')+' 기준 · 범주 간 중복 가능 · 셀을 눌러 업무 확인</span></div><div class="weekly-total-bars">'+Object.entries(buckets).map(([k,label])=>'<div class="weekly-total" data-week-total="'+k+'"><span>'+label+'</span><b>'+totals[k]+'<small>건</small></b><div class="aggregate-track"><i style="width:'+(totals[k]/totalMax*100)+'%"></i></div></div>').join('')+'</div><p class="comparison-note">네 합계 공통 척도 0–'+totalMax+'건 · 범주 간 중복 가능</p><details class="fold-section" id="weekly-details"><summary><strong>제품군별 주간 비교</strong><small>펼쳐서 제품군별 네 범주를 동시에 비교</small></summary><section class="panel tablewrap compact"><table class="weekly-matrix visual-weekly"><thead><tr><th>제품군</th>'+Object.values(buckets).map(v=>'<th>'+v+'</th>').join('')+'</tr></thead><tbody>'+wl.map(l=>'<tr><td>'+esc(l.name)+'</td>'+Object.keys(buckets).map(k=>{const n=(l[k]||[]).length;return '<td><button class="weekly-bar-button" data-week-line="'+esc(l.name)+'" data-week-bucket="'+k+'" aria-label="'+esc(l.name+' '+buckets[k]+' '+n+'건 상세')+'"><span style="width:'+(n/max*100)+'%"></span><b>'+n+'</b></button></td>';}).join('')+'</tr>').join('')+'</tbody></table></section></details>';}
function raRecordsContent(){if(!R)return empty('전사 인허가 스냅숏이 없습니다.');const full=raExpandedContent(),head='<div class="sectionhead">';const at=label=>full.lastIndexOf(head,full.indexOf('<h2>'+label));const registry=at('제품 등록부'),duties=at('갱신·만료 및 후속 의무'),company=at('회사 허가·인증'),requests=at('요청 처리 현황');if([registry,duties,company,requests].some(n=>n<0))return empty('인허가 화면 구조를 확인하지 못했습니다.');const urgentEnd=full.indexOf('<div class="summary-strip">');const q=$('#ra-search').value.trim().toLowerCase();const allRequests=(R.open_requests||[]).filter(x=>!q||String(x.subject||'').toLowerCase().includes(q));const urgent=allRequests.filter(x=>x.review_delay||(x.desired&&x.desired<R.today));const nextRequest=allRequests.flatMap(x=>[x.desired,x.due].filter(Boolean).filter(d=>d>=R.today).map(d=>({...x,nextDate:d}))).sort((a,b)=>a.nextDate.localeCompare(b.nextDate))[0];const modelRows=(full.slice(registry,duties).match(/<td><strong>/g)||[]).length;const companyRows=(full.slice(company,requests).match(/<tr><td>(?!<)/g)||[]).length;const obCount=(R.registry?.obligations||[]).filter(o=>($('#market').value==='all'||o.country===$('#market').value)&&(o.scope==='company'||$('#family').value==='all'||o.family===$('#family').value)&&(!q||[o.kind,o.type,o.family,o.country,...(o.models||[])].join(' ').toLowerCase().includes(q))).length;const fold=(id,title,count,unit,body)=>'<details class="fold-section" id="'+id+'"><summary><strong>'+title+'</strong><span class="fold-meta">'+count+' '+unit+'</span><small>펼쳐서 전체 내역 확인</small></summary>'+body+'</details>';return full.slice(0,urgentEnd)+'<section class="panel compact urgent-requests" id="urgent-requests"><div class="paneltitle"><h3>후속 확인이 필요한 요청</h3><small>전사 · 검색만 적용</small></div>'+urgent.map(x=>'<div class="urgent-request"><div><strong>'+esc(x.subject)+'</strong><small>'+esc(x.status)+' · '+(x.review_delay?'원본 규칙상 검토 지연':'')+(x.review_delay&&x.desired&&x.desired<R.today?' / ':'')+(x.desired&&x.desired<R.today?'희망일 '+esc(x.desired)+' 경과':'')+'</small></div>'+link(x)+'</div>').join('')+(urgent.length?'':'<p>현재 검색 범위에 검토 지연·희망일 경과 신호가 없습니다.</p>')+(nextRequest?'<div class="next-request"><strong>다음 등록 마감 · '+esc(nextRequest.nextDate)+'</strong><span>'+esc(nextRequest.subject)+'</span>'+link(nextRequest)+'<small>스냅숏 기준 가장 가까운 희망일·마감일 · 지연·승인 판단이 아닙니다.</small></div>':'')+'<p class="comparison-note">실제 검토 지연 플래그 또는 스냅숏 기준일보다 앞선 희망일만 표시합니다. 시장·제품군은 요청 식별자가 없어 적용하지 않습니다.</p></section>'+fold('ra-registry-details','제품 등록부',Math.max(0,modelRows),'표시 행 · 모델×시장',full.slice(registry,duties))+fold('ra-obligations-details','전체 의무 일정',obCount,'의무',full.slice(duties,company))+fold('ra-company-details','회사 허가·인증',Math.max(0,companyRows),'표시 행 · 회사 자격',full.slice(company,requests))+fold('ra-requests-details','전체 열린 요청',allRequests.length,'요청',full.slice(requests));}

function raContent(){if(!R)return empty('전사 인허가 스냅숏이 없습니다.');const reg=R.registry||{},market=$('#market').value,family=$('#family').value,q=$('#ra-search').value.trim().toLowerCase(),match=v=>!q||String(v).toLowerCase().includes(q);const obligations=(reg.obligations||[]).filter(o=>(o.scope==='company'||family==='all'||o.family===family)&&(market==='all'||o.country===market)&&match([o.kind,o.type,o.country,o.family,...(o.models||[])].join(' '))&&(o.overdue||(o.date&&o.date<=addDays(R.today,90))));const req=(R.open_requests||[]).filter(x=>match(x.subject)).flatMap(x=>[x.desired,x.due].filter(d=>d&&d>=R.today).map(date=>({...x,date}))).sort((a,b)=>a.date.localeCompare(b.date))[0];const events=[...obligations.map(o=>({date:o.date,title:o.type+' · '+o.kind,kind:o.scope==='company'?'◆ 회사 공통 의무':'◇ 제품 의무',sub:o.country+(o.scope==='company'?' · 회사 공통 · 제품군 필터 제외':' · 제품 범위'),id:null})),...(req?[{date:req.date,title:req.subject,kind:'● 요청 등록 마감',sub:'전사 요청 · 검색만 적용',id:req.id}]:[])].filter(e=>e.date).sort((a,b)=>a.date.localeCompare(b.date));const all=[R.today,...events.map(e=>e.date)].sort(),start=all[0],end=all.at(-1),span=Math.max(86400000,Date.parse(end)-Date.parse(start)),pos=d=>4+(Date.parse(d)-Date.parse(start))/span*92;const markets=(reg.columns||[]).filter(m=>market==='all'||m===market),families=Object.keys(reg.family_models||{}).filter(f=>family==='all'||f===family);return '<section class="visual-deadlines panel compact"><div class="visual-heading"><h2>인허가 일정</h2><span>스냅숏 '+esc(R.today)+' 기준 · 오늘의 남은 일수가 아님</span></div><div class="deadline-axis"><span>'+esc(start)+'</span><span>'+esc(end)+'</span></div>'+events.map(e=>'<div class="deadline-event"><div><strong>'+esc(e.kind)+'</strong><span>'+esc(e.title)+'</span><small>'+esc(e.sub)+'</small></div><div class="deadline-track"><span class="reference-mark" style="left:'+pos(R.today)+'%"></span><span class="deadline-connector" style="left:'+Math.min(pos(R.today),pos(e.date))+'%;width:'+Math.abs(pos(e.date)-pos(R.today))+'%"></span><span class="deadline-point" style="left:'+pos(e.date)+'%">'+(e.id?'●':'◆')+'</span></div><div class="deadline-date"><b>'+esc(e.date)+'</b><span>'+Math.round((Date.parse(e.date)-Date.parse(R.today))/86400000)+'일 후</span>'+(e.id?link(e):'')+'</div></div>').join('')+(events.length?'':empty('조회 범위의 일정이 없습니다.'))+'<p class="comparison-note">세로선=스냅숏 기준일 · 회사 공통 의무는 제품군 필터 제외 · 등록 날짜이며 승인·실제 완료 판단 아님.</p></section><div class="visual-heading"><h2>제품군 × 시장 등록 상태</h2><span>모델·시장 셀의 실제 상태 건수 · 미표시는 미취득 확정 아님</span></div><section class="panel compact tablewrap"><table class="ra-status-matrix"><thead><tr><th>제품군</th>'+markets.map(m=>'<th>'+esc(m)+'</th>').join('')+'</tr></thead><tbody>'+families.map(f=>'<tr><td><strong>'+esc(f)+'</strong></td>'+markets.map(m=>{const cells=(reg.family_models[f]||[]).filter(x=>match([f,x.model,x.series,m,...(x.cells?.[m]?.types||[])].join(' '))).map(x=>x.cells?.[m]).filter(Boolean),states={};cells.forEach(c=>states[c.state||'미제공']=(states[c.state||'미제공']||0)+1);return '<td>'+(cells.length?'<div class="state-segments">'+Object.entries(states).map(([state,n])=>'<span class="state-segment '+(state==='유효'?'valid':state==='만료'?'expired':'other')+'" style="flex:'+n+'" title="'+esc(state+' '+n+'개 모델·시장 셀')+'">'+esc(state)+' '+n+'</span>').join('')+'</div>':'<span class="no-data">자료 없음</span>')+'</td>';}).join('')+'</tr>').join('')+'</tbody></table></section>'+raRecordsContent().replace(/^<div class="sectionhead">[\s\S]*?(?=<section class="panel compact urgent-requests")/,'');}

const SELECTION_KEY='dr-portfolio-included-projects-v1';
function allProjectIds(){return [...new Set((I?.product_lines||[]).filter(l=>!l.regulatory).flatMap(l=>l.projects||[]))];}
function activeProjectIds(){const all=allProjectIds();if(localIncluded!==null)return all.filter(id=>localIncluded.includes(id));return scopeConfig?all.filter(id=>!scopeConfig.excluded.includes(id)):null;}
function loadLocalSelection(){try{const saved=JSON.parse(localStorage.getItem(SELECTION_KEY)||'null');localIncluded=saved&&saved.version===1&&Array.isArray(saved.included)&&saved.included.every(id=>typeof id==='string')?saved.included.filter(id=>allProjectIds().includes(id)):null;}catch{localIncluded=null;}}
