/* Last viewed state is a separate device preference, not business data. */
const VIEW_PREFERENCE_KEY='dr-portfolio-view-state-v1';
function defaultViewPreferences(){return {version:1,lastView:'dev',dev:{scope:'all',search:'',range:9,taskSort:'source',details:{},scrollY:0},ra:{market:'all',family:'all',search:'',details:{},scrollY:0}};}
function parseViewPreferences(saved){const result=defaultViewPreferences();if(!saved||saved.version!==1)return result;result.lastView=saved.lastView==='ra'?'ra':'dev';for(const domain of ['dev','ra']){const src=saved[domain];if(!src||typeof src!=='object')continue;for(const field of domain==='dev'?['scope','search']:['market','family','search'])if(typeof src[field]==='string')result[domain][field]=src[field];if(src.details&&typeof src.details==='object'&&!Array.isArray(src.details))result[domain].details=Object.fromEntries(Object.entries(src.details).filter(([k,v])=>typeof v==='boolean'));if(Number.isFinite(src.scrollY)&&src.scrollY>=0)result[domain].scrollY=Math.min(10000000,src.scrollY);}if(['source','due','product'].includes(saved.dev?.taskSort))result.dev.taskSort=saved.dev.taskSort;if([9,15].includes(saved.dev?.range))result.dev.range=saved.dev.range;return result;}
function readViewPreferences(){try{return parseViewPreferences(JSON.parse(localStorage.getItem(VIEW_PREFERENCE_KEY)||'null'));}catch{return defaultViewPreferences();}}
let viewPreferences=readViewPreferences(),viewPreferencesReady=false,viewPreferenceTimer=null,viewScrollRestorePending=false,restoringViewScroll=false,viewPreferenceStorageFailed=false;
