function viewDetailKey(node){if(node.id)return 'id:'+node.id;if(node.matches('.project-details')){const name=node.closest('tr')?.querySelector('[data-line]')?.dataset.line;return name?'product:'+name:null;}if(node.matches('.timeline-disclosure'))return 'all-milestones';return null;}
function captureViewDetails(domain){const root=$('#content');if(!viewPreferencesReady||!root?.children)return;for(const node of root.querySelectorAll('details')){const key=viewDetailKey(node);if(key)viewPreferences[domain].details[key]=node.open;}}
function restoreViewDetails(domain){const root=$('#content');if(!root?.children)return;root.dataset.preferenceDomain=domain;for(const node of root.querySelectorAll('details')){const key=viewDetailKey(node);if(key&&Object.prototype.hasOwnProperty.call(viewPreferences[domain].details,key))node.open=viewPreferences[domain].details[key];}}
function optionExists(select,value){return [...(select.options||[])].some(o=>o.value===value);}
function restoreInitialViewPreferences(){const fallbacks=[];for(const [selector,domain,field] of [['#scope','dev','scope'],['#market','ra','market'],['#family','ra','family']]){const select=$(selector),saved=viewPreferences[domain][field];if(optionExists(select,saved))select.value=saved;else{select.value='all';viewPreferences[domain][field]='all';if(saved!=='all')fallbacks.push(saved);}}$('#task-sort').value=viewPreferences.dev.taskSort;$('#search').value=viewPreferences.dev.search;$('#ra-search').value=viewPreferences.ra.search;viewPreferencesReady=true;viewScrollRestorePending=true;if(fallbacks.length){const note=$('#view-preference-status');if(note)note.textContent='자료에서 사라진 필터('+fallbacks.join(', ')+')는 전체 범위로 복원했습니다.';}}
function restoreViewScroll(domainChanged){if(!viewPreferencesReady||(!domainChanged&&!viewScrollRestorePending)||typeof requestAnimationFrame!=='function'||typeof window.scrollTo!=='function')return;viewScrollRestorePending=false;restoringViewScroll=true;const y=viewPreferences[view].scrollY;requestAnimationFrame(()=>{window.scrollTo(0,y);requestAnimationFrame(()=>{restoringViewScroll=false;});});}
function captureViewFilters(){if(!viewPreferencesReady)return;viewPreferences.dev.taskSort=['source','due','product'].includes($('#task-sort').value)?$('#task-sort').value:'source';viewPreferences.dev.scope=$('#scope').value||'all';viewPreferences.dev.search=$('#search').value;viewPreferences.ra.market=$('#market').value||'all';viewPreferences.ra.family=$('#family').value||'all';viewPreferences.ra.search=$('#ra-search').value;viewPreferences.lastView=view;queueViewPreferenceSave();}
for(const id of ['scope','search','market','family','ra-search'])$('#'+id).addEventListener(id==='search'||id==='ra-search'?'input':'change',captureViewFilters);
$('#reset').addEventListener('click',captureViewFilters);$('#ra-reset').addEventListener('click',captureViewFilters);
document.addEventListener('change',e=>{if(e.target.id==='range'&&[9,15].includes(Number(e.target.value))){viewPreferences.dev.range=Number(e.target.value);queueViewPreferenceSave();}});
document.addEventListener('toggle',e=>{const node=e.target,root=$('#content');if(!viewPreferencesReady||!node.matches?.('details')||!root.contains(node))return;const key=viewDetailKey(node);if(key){viewPreferences[view].details[key]=node.open;queueViewPreferenceSave();}},true);
window.addEventListener('scroll',()=>{if(viewPreferencesReady&&!restoringViewScroll){viewPreferences[view].scrollY=Math.max(0,window.scrollY||0);queueViewPreferenceSave();}},{passive:true});
window.addEventListener('pagehide',()=>{captureViewDetails(view==='ra'?'ra':'dev');captureViewFilters();flushViewPreferences();});
// Explicit incoming domain links win; reopening without a domain returns to the last view.
function consumeDashboardView(){const hash=location.hash,requested=hash==='#ra'?'ra':hash==='#dev'?'dev':viewPreferences.lastView;if(hash==='#dev'||hash==='#ra'){viewPreferences.lastView=requested;history.replaceState(history.state,'',location.pathname+location.search);}return requested;}
document.addEventListener('click',e=>{const link=e.target.closest('nav a[data-view],.brand[href="#dev"]');if(!link)return;e.preventDefault();viewPreferences.lastView=link.dataset.view==='ra'?'ra':'dev';render();});
consumeDashboardView();


/* Same-origin loopback reader: latest source snapshots, never writes source records. */
let historicalSnapshots=null,liveBundleMeta=null,liveBusy=false,liveReaderError=null,liveFingerprint=null,liveStarted=false,liveLastBundle=null,liveDeferred=false,liveClientAttemptAt=null,liveClientErrorAt=null;
function snapshotFieldDisclosure(){return '담당은 집계 자료의 실제 assignee 필드만 표시합니다. 승인 정보는 집계 자료에 수록되지 않았습니다. 원본 링크에서 확인할 수 있습니다.';}
function liveContentFingerprint(bundle){return JSON.stringify({dev:bundle.dev,ra:bundle.ra,config:bundle.config});}
function validLiveDev(value){return value&&['health','insights','weekly'].every(n=>value[n]&&Number.isFinite(Date.parse(value[n].generated_at)))&&Array.isArray(value.health.items)&&Array.isArray(value.health.project_health)&&Array.isArray(value.insights.product_lines)&&Array.isArray(value.insights.project_status)&&Array.isArray(value.insights.milestones)&&Array.isArray(value.weekly.lines);}
function refreshRAFilterOptions(){for(const [id,values] of [['market',R?.registry?.columns||[]],['family',R?.registry?.families||[]]]){const select=$('#'+id),previous=select.value;select.innerHTML='<option value="all">'+(id==='market'?'전체 시장':'전체 제품군')+'</option>';for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option);}if(previous==='all'||values.includes(previous))select.value=previous;else{select.value='all';$('#view-preference-status').textContent='최신 자료에서 사라진 필터('+previous+')는 전체 범위로 바꿨습니다.';}}}
function applyLatestBundle(bundle){if(!bundle||bundle.version!==1||!validLiveDev(bundle.dev)||!bundle.meta)throw Error('최신 자료 형식 검증 실패');liveBundleMeta=bundle.meta;liveLastBundle=bundle;const fingerprint=liveContentFingerprint(bundle);if(fingerprint===liveFingerprint){for(const node of $('#content')?.querySelectorAll?.('[data-task-evidence]')||[]){const id=Number(node.dataset.taskEvidence),item=H.items.find(x=>Number(x.id)===id),open=node.querySelector('details')?.open;if(item){node.outerHTML=taskEvidence(item);const details=$('#task-evidence-'+id);if(details)details.open=!!open;}}updateLiveStatus();return false;}if(layoutPointer||$('#selection-dialog')?.open){liveDeferred=true;updateLiveStatus('새 자료 확인됨 · 현재 편집이 끝난 뒤 다음 확인 때 반영합니다.');return false;}liveDeferred=false;const scroll=typeof window.scrollY==='number'?window.scrollY:0;captureViewDetails(view);H=bundle.dev.health;I=bundle.dev.insights;rawWeekly=bundle.dev.weekly;if(bundle.ra&&Array.isArray(bundle.ra.open_requests)&&bundle.ra.registry)R=bundle.ra;const config=bundle.config;if(config&&config.version===1&&Array.isArray(config.excluded)&&config.excluded.every(x=>typeof x==='string')&&Number.isFinite(Date.parse(config.updated_at)))scopeConfig=config;applySelectionScope();const previousScope=$('#scope').value;rebuildScopeOptions();refreshRAFilterOptions();if(previousScope!=='all'&&$('#scope').value==='all')$('#view-preference-status').textContent='최신 원본 자료에 제품군('+previousScope+')이 없어 조회 범위를 전체로 전환했습니다. 관심 과제·서버 설정은 변경하지 않았습니다.';captureViewFilters();liveFingerprint=fingerprint;render();if(typeof requestAnimationFrame==='function'&&typeof window.scrollTo==='function'){restoringViewScroll=true;requestAnimationFrame(()=>{window.scrollTo(0,scroll);requestAnimationFrame(()=>{restoringViewScroll=false;});});}return true;}
function updateLiveStatus(extra=''){if(!H||!I)return;const domain=view==='ra'?'ra':'dev',m=liveBundleMeta?.[domain],generated=view==='ra'?(R?.generated||R?.registry?.synced_at):H.generated_at;let text='집계 생성 '+(Number.isFinite(Date.parse(generated))?evidenceKST(generated):'미확인');if(m?.source_checked_at)text+=' · 읽기 확인 '+evidenceKST(m.source_checked_at);if(liveBusy)text+=' · 확인 중';if(m?.error)text+=' · 원본 조회 실패: '+m.error+' · 마지막 정상 자료 유지';else if(m?.status!=='source')text+=' · 보관 자료 표시 · 최신 확인 안 됨';if(liveReaderError)text+=' · 로컬 조회 실패 '+(liveClientErrorAt?evidenceKST(liveClientErrorAt):'시각 미확인')+' · '+liveReaderError+' · 마지막 정상 자료 유지';if(liveDeferred)text+=' · 새 자료 반영 대기(현재 편집 유지)';if(extra)text+=' · '+extra;$('#snapshot').textContent=text;$('#snapshot').classList.toggle('source-read-warning',!!liveReaderError||!!m?.error||m?.status!=='source');const button=$('#data-refresh');if(button){button.disabled=liveBusy;button.textContent=liveBusy?'자료 확인 중…':'자료 새로 확인';}const warning=$('#basis')?.parentElement?.querySelector('small');if(warning)warning.textContent=m?.status==='source'?'수동 확인':'보관 자료';}
async function readStaticSourceBundle(){const names=['health','insights','weekly','ra','config/tracked-projects'],values=await Promise.all(names.map(async name=>{const response=await fetch('/data/'+name+'.json',{cache:'no-store'});if(!response.ok)throw Error('집계 자료 '+name+' HTTP '+response.status);return response.json();})),dev={health:values[0],insights:values[1],weekly:values[2]},ra=values[3],config=values[4];if(!validLiveDev(dev))throw Error('개발 집계 자료 형식 확인 필요');const stamps=Object.values(dev).map(value=>Date.parse(value.generated_at)),days=new Set(Object.values(dev).map(value=>value.today).filter(Boolean));if(days.size>1||Math.max(...stamps)-Math.min(...stamps)>120000)throw Error('개발 집계 시각 불일치 · 이전 자료 유지');if(!Array.isArray(ra?.open_requests)||!ra?.registry||!Number.isFinite(Date.parse(ra.generated)))throw Error('인허가 집계 자료 형식 확인 필요');if(config?.version!==1||!Array.isArray(config.excluded)||!config.excluded.every(value=>typeof value==='string')||!Number.isFinite(Date.parse(config.updated_at)))throw Error('관심 과제 기준 자료 형식 확인 필요');const checked=new Date().toISOString(),meta=Object.fromEntries(['dev','ra','config'].map(domain=>[domain,{status:'source',source_checked_at:checked,last_success_at:checked,error:null}]));return {version:1,dev,ra,config,meta};}
async function checkLatestData(force=false){if(liveBusy)return;liveClientAttemptAt=new Date().toISOString();liveBusy=true;updateLiveStatus();try{const response=await fetch('/runtime/dashboard'+(force?'?force=1':''),{cache:'no-store'});if(!response.ok&&response.status!==404)throw Error('최신 읽기 서버 HTTP '+response.status);const bundle=response.status===404?await readStaticSourceBundle():await response.json();liveReaderError=null;liveClientErrorAt=null;applyLatestBundle(bundle);}catch(error){liveClientErrorAt=new Date().toISOString();liveReaderError=String(error.message||error); }finally{liveBusy=false;updateLiveStatus();}}
function startLiveUpdates(){if(liveStarted)return;liveStarted=true;checkLatestData(false);}
$('#data-refresh').addEventListener('click',()=>checkLatestData(true));

function applyDeferredLiveData(){if(liveDeferred&&liveLastBundle&&!layoutPointer&&!$('#selection-dialog')?.open)applyLatestBundle(liveLastBundle);}
document.addEventListener('close',e=>{if(e.target.id==='selection-dialog')applyDeferredLiveData();},true);
document.addEventListener('pointerup',()=>{if(typeof setTimeout==='function')setTimeout(applyDeferredLiveData,0);});
document.addEventListener('pointercancel',()=>{if(typeof setTimeout==='function')setTimeout(applyDeferredLiveData,0);});

function taskEvidence(item){const checked=liveBundleMeta?.dev?.source_checked_at;return '<div class="task-evidence" data-task-evidence="'+item.id+'"><small class="role-source">집계 기준</small><strong>'+esc(taskOwnerEvidence(item))+'</strong><span>승인 정보 미수집</span><details id="task-evidence-'+item.id+'"><summary>출처·시각</summary><small>역할 출처: 집계 자료 · '+link(item)+'</small><small>집계 생성 '+esc(evidenceKST(H.generated_at))+'</small>'+(checked?'<small>읽기 확인 '+esc(evidenceKST(checked))+'</small>':'<small>읽기 확인시각 미수록</small>')+'<small>조회 당시 값 · 수동 확인</small></details></div>';}

$('#task-sort').addEventListener('change',()=>{captureViewFilters();render();});

function liveReadDetails(){const m=liveBundleMeta?.[view==='ra'?'ra':'dev'];return '<h3>읽기 근거</h3><p>열기·새로고침·자료 새로 확인 시 조회합니다. 집계는 실시간 상태와 다를 수 있습니다.</p><p>'+snapshotFieldDisclosure()+'</p><p>원본 읽기 시도: '+(m?.last_attempt_at?esc(evidenceKST(m.last_attempt_at)):'미확인')+'<br>마지막 성공: '+(m?.last_success_at?esc(evidenceKST(m.last_success_at)):'미확인')+'<br>이 화면 읽기 시도: '+(liveClientAttemptAt?esc(evidenceKST(liveClientAttemptAt)):'미확인')+'</p>'; }
